export const buildDotSymbols = async (
		outPath: string = 'src/.symbols',
		trace: boolean = false
		): AutoPromise<void> => {

	const outfile = new CWritableFile(outPath)
	for (const path of allFilesMatching('**/*.lib.ts')) {
		try {
			const infile = new CReadableFile(path)
			const contents = await infile.getContents()
			const analysis = analyzeTsCode(contents)
			const lExports = analysis.getExports()
			const {stub} = parsePath(path)

			await outfile.writeln(stub)
			let numSymbols = 0
			for (const line of allExportLines(lExports)) {
				await outfile.writeln(indented(line))
				if (trace) {
					numSymbols += words(line).length
				}
			}
			if (trace) {
				LOG(f`${numSymbols}:3 ${toRelPath(path)}`)
			}
		}
		catch (err) {
			ERR(getErrStr(err) + ` in ${path}`)
		}
	}
}

